    /**
     * Tests creating a new FXDeal.
     *
     * @return    FXDeal
     */
    public FXDeal testCreate() throws Throwable {
    FXDeal entity = null;

    LOGGER.info( "FXDealTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a FXDeal");

    StringBuilder msg = new StringBuilder( "-- Failed to create a FXDeal" );

    try {
        entity = service.createFXDeal( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getFXDealId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a FXDeal with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

