    /**
     * Tests getting all FXDeals.
     *
     * @return    Collection
     */
    public List<FXDeal> testGetAll() throws Throwable {
    LOGGER.info( "FXDealTest:testGetAll() - Retrieving Collection of FXDeals:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all FXDeal : " );
    List<FXDeal> collection  = null;

    try {
        // call the static get method on the FXDealService
        collection = service.getAllFXDeal();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            FXDeal currEntity  = null;
            Iterator<FXDeal> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getFXDealId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

